-- Published bundles (object key + sha256) are produced by the backend on start.
INSERT INTO scenario_version (id, alarm_definition_id, version, status, published_at)
SELECT ('0f' || substr(id::text, 3))::uuid, id, 1, 'PUBLISHED', now() - interval '7 days' FROM alarm_definition;

UPDATE alarm_definition SET current_scenario_version_id = ('0f' || substr(id::text, 3))::uuid;

