-- The crisis operator manages every other Kraków alarm type.
INSERT INTO alarm_controller (person_id, alarm_definition_id, can_raise, can_cancel)
SELECT '0b000000-0000-0000-0000-000000001001', id, true, true FROM alarm_definition
WHERE organization_id = '0a000000-0000-0000-0000-000000000001'
  AND code NOT IN ('DRONE_STRIKE', 'AIR_RAID');

